let globalIslands=[],indexLimit=100,indexLetter='All',globalIslandsLoaded=false,globalIslandsLoading=false;
const indexNameCounts=new Map();
const countryNames=new Intl.DisplayNames(['en'],{type:'region'});
const islandNameKey=name=>name.normalize('NFD').replace(/[\u0300-\u036fʻ’']/g,'').toLowerCase();
async function loadGlobalIslands(){
 if(globalIslandsLoaded||globalIslandsLoading)return;globalIslandsLoading=true;
 try{
  const [res,review]=await Promise.all([fetch('/data/world-islands.json'),reviewReady]);if(!res.ok)throw Error('Global index unavailable');const data=await res.json();
  const aliases=new Set([...curatedGeoNamesIds,...(review?.curatedAliases||[])]),duplicates=review?.duplicateOf||{};
  globalIslands=data.filter(x=>!aliases.has(x.sourceId)&&!duplicates[x.sourceId]).map(x=>[x.name,x.countryCode?countryNames.of(x.countryCode):'Not recorded','Region not recorded',x.latitude,x.longitude,x.sourceId]);
  indexNameCounts.clear();for(const r of [...registry,...globalIslands]){const key=islandNameKey(r[0]);indexNameCounts.set(key,(indexNameCounts.get(key)||0)+1)}
  globalIslandsLoaded=true;renderIndex();
 }catch{const note=document.createElement('p');note.textContent='Global index unavailable. Reload to retry.';$('indexList').append(note)}finally{globalIslandsLoading=false}
}
function renderIndex(){
 renderIndexAlphabet();
 const q=$('indexSearch').value.trim().toLowerCase(),sort=Number($('indexSort').value),filter=$('indexStatus').value,out=$('indexList');out.replaceChildren();
 const rows=selectIndexRows([...registry,...globalIslands],{query:q,letter:indexLetter,status:filter,sort},r=>Boolean(!r[5]&&draftIds[r[0]]));
 for(const r of rows.slice(0,indexLimit)){const row=document.createElement('button');row.className='index-list-entry';const name=document.createElement('strong');name.textContent=r[0];if((indexNameCounts.get(islandNameKey(r[0]))||0)>1||[1,4].includes(sort)){const location=document.createElement('small');location.className='index-location';location.textContent=r[1]+((indexNameCounts.get(islandNameKey(r[0]))||0)>1?' · '+r[3].toFixed(3)+', '+r[4].toFixed(3):'');name.append(location)}const status=document.createElement('span');status.textContent=(!r[5]&&draftIds[r[0]])?'Exists':'Not existing';row.append(name,status);row.onclick=()=>openIsland(r,null,{fromIndex:true});out.append(row);}
 const count=document.createElement('p');count.textContent=rows.length.toLocaleString('en-US')+' matching islands · '+(globalIslands.length?'GeoNames CC BY 4.0 + curated registry':'Curated registry · global import pending');out.append(count);if(rows.length>indexLimit){const more=document.createElement('button');more.textContent='Show more';more.onclick=()=>{indexLimit+=100;renderIndex()};out.append(more);}
}
function renderIndexAlphabet(){
 const alphabet=$('indexAlphabet');
 if(!alphabet.children.length){for(const letter of indexLetters){const button=document.createElement('button');button.type='button';button.textContent=letter;button.dataset.letter=letter;button.setAttribute('aria-label',letter==='All'?'All initials':letter==='#'?'Other initials':'Islands starting with '+letter);if(letter==='#')button.title='Numbers and other scripts';button.onclick=()=>{indexLetter=letter;indexLimit=100;renderIndex()};alphabet.append(button)}}
 for(const button of alphabet.children){const active=button.dataset.letter===indexLetter;button.setAttribute('aria-pressed',String(active));button.classList.toggle('is-active',active)}
}
