function openIsland(r,selectedEdition=null,{fromIndex=false}={}){
 currentIslandDetail={record:r,selectedEdition,options:{fromIndex}};
 const out=$('islandDetailContent');out.replaceChildren();const id=r[5]?null:draftIds[r[0]];
 if(adminPreview.state().active){const badge=document.createElement('p');badge.className='admin-preview-note';badge.textContent='ADMINISTRATOR PREVIEW · unreleased artwork';out.append(badge)}
 const title=document.createElement('h1');title.textContent=r[0];const geo=document.createElement('p');geo.textContent=r[1]+' · '+r[2];out.append(title,geo,islandDetails(r[0],r));
 for(const e of ['N','S']){
  const cell=document.createElement('article');cell.className='panel';
  if(id){cell.id='edition-'+id+'-'+e;cell.tabIndex=-1;cell.classList.toggle('selected-edition',selectedEdition===id+'-'+e)}
  const heading=document.createElement('h2');heading.textContent=e==='N'?'North-Up':'South-Up';cell.append(heading);
  const edition=id?findEdition(id+'-'+e):null;
  const state=editionStatus({artworkExists:Boolean(id),collectionReleased,chain:edition?.chain}),reveal=revealIndexArtwork({fromIndex:true,mint:state.mint,administrator:adminPreview.state().active});
  cell.append(editionRecord(Boolean(id),edition?.chain));
  if(id){
   if(reveal){
    const img=document.createElement('img');img.src=edition.image;img.alt=r[0]+' '+heading.textContent;img.style.width='100%';cell.append(img);
    const actions=document.createElement('div');actions.className='artwork-actions';actions.append(shareLink(edition),farcasterShareLink(edition));cell.append(actions);
   }else cell.append(artworkMystery(state.mint==='Not minted'?'Artwork revealed after mint':'Mint status not verified'));
   fetch(edition.image.replace(/\.png$/,'.json')).then(res=>{if(!res.ok)throw Error();return res.json()}).then(m=>{
    const t=draftTraits[r[0]],j=e==='N'?0:1;
    const attributes={'Island ID':id,'Artwork ID':id+'-'+e,'Island':r[0],'Country':r[1],'Region':t[0],'Island Type':t[1],'Water Type':t[2],'Ocean':t[3],'Water Body':t[4],'Largest Settlement':t[9]??null,'Area':m.area_km2==null?null:Number(m.area_km2).toLocaleString('en-US',{maximumFractionDigits:3})+' km²','Scale':m.artwork_print_scale_denominator?'1:'+Math.round(m.artwork_print_scale_denominator).toLocaleString('en-US'):null,'Orientation':heading.textContent};
    if(reveal)Object.assign(attributes,{'Color Palette':m.color_mood,'Color Family':t[5+j],'Background':t[7+j]});
    const dl=document.createElement('dl');dl.className='edition-traits';
    for(const [k,v] of Object.entries(attributes)){if(v==null)continue;const dt=document.createElement('dt');dt.textContent=k;const dd=document.createElement('dd');dd.textContent=v;dl.append(dt,dd)}
    cell.append(dl);const note=document.createElement('small');note.textContent='Draft traits · geographic and licensing review pending';cell.append(note);
   }).catch(()=>{const note=document.createElement('p');note.textContent='Artwork metadata unavailable';cell.append(note)});
  }else{
   cell.append(artworkMystery('Artwork not created yet'));
  }
  cell.append(acquisitionButtons(state,edition));
  out.append(cell);
 }
 show('islandDetail');
 if(id){const editionId=selectedEdition||id+'-N';history.replaceState(null,'',editionUrl(editionId,location.origin,{fromIndex}));if(selectedEdition){const target=$('edition-'+selectedEdition);target?.focus({preventScroll:true});target?.scrollIntoView({block:'start'});}}
}
function artworkMystery(caption){
 const box=document.createElement('div');box.className='artwork-mystery';box.setAttribute('role','img');box.setAttribute('aria-label',caption);
 const question=document.createElement('strong');question.textContent='?';question.setAttribute('aria-hidden','true');const note=document.createElement('p');note.textContent=caption;box.append(question,note);return box;
}
