let keyQuote=null;function displayUsd(){const fmt=n=>n.toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:4});$('usdquote').textContent=keyQuote===null?'KEY market quote unavailable':'≈ '+fmt(500000*keyQuote)+' USD equivalent · KEY reference price';$('discountusd').textContent=keyQuote===null?'USD estimate unavailable':'≈ '+fmt(Number(mintPrice('500000',Number($('keysRange').value)))*keyQuote)+' USD equivalent · simulated discount';} $('keysRange').addEventListener('input',displayUsd);async function refreshQuote(){try{const r=await fetch('/api/key-price');if(!r.ok)throw Error();const q=await r.json();if(q.token!=='0xb0ca1e094a1779018b194ac6151ece8d6f05db07'||!Number.isFinite(Number(q.priceUsd))||Number(q.priceUsd)<=0)throw Error();keyQuote=Number(q.priceUsd);}catch{keyQuote=null}displayUsd()}refreshQuote();setInterval(refreshQuote,60000);

async function initFarcaster(){
 const initialAttempt=walletAttempt;
 try{
  miniApp=await sdk.isInMiniApp();
  if(miniApp){
   Promise.resolve().then(()=>sdk.actions.ready()).catch(()=>{});
   const provider=await resolveFarcasterProvider(sdk,{timeout:2500});
   const accounts=await withTimeout(provider.request({method:'eth_accounts'}),4000,'Farcaster account lookup timed out.');
   if(walletAttempt===initialAttempt&&!connectedProvider&&accounts?.[0])setConnectedWallet(provider,accounts);
  }else if(window.ethereum){
   const accounts=await window.ethereum.request({method:'eth_accounts'});
   if(walletAttempt===initialAttempt&&!connectedProvider&&accounts?.[0])setConnectedWallet(window.ethereum,accounts);
  }
 }catch{/* Explicit connection remains available even if initial detection failed. */}
}
initFarcaster();
const galleryQuery=new URLSearchParams(location.search).get('gallery');
if(galleryQuery){$('gallerySearch').value=galleryQuery;renderGallery();}
 const requestedEdition=new URLSearchParams(location.search).get('edition');
if(requestedEdition){if(!openEdition(requestedEdition,{fromIndex:new URLSearchParams(location.search).get('view')==='index'})){show('gallery');$('status').textContent='Artwork edition not found.';}}else if(new URLSearchParams(location.search).has('mint')){
 const query=new URLSearchParams(location.search),mode=query.get('mint'),destination=query.get('destination');
 if(['blind','regional'].includes(mode))openMint(mode);
 else if(mode==='direct'&&findEdition(destination))openMint('direct',destination);
 else if(mode==='direct'&&!destination){selectMintMode('direct');show('discover');}
 else{$('status').textContent='Mint selection unavailable. Choose an island from the Index.';show('index');}
}else if(location.hash==='#index')show('index');else if(location.hash==='#gallery')show('gallery');else if(location.hash==='#leaderboards')show('cheers');

function shareLink(edition){
 const link=document.createElement('a');link.href=xShareUrl(edition,location.origin);link.target='_blank';link.rel='noopener noreferrer';link.className='artwork-link share-on-x';link.textContent='Share on X ↗';link.setAttribute('aria-label','Share '+edition.name+' '+edition.orientation+' on X');return link;
}
function farcasterShareLink(edition){
 const link=document.createElement('a');link.href=farcasterShareUrl(edition,location.origin);link.target='_blank';link.rel='noopener noreferrer';link.className='artwork-link share-on-farcaster';link.textContent='Share on Farcaster ↗';link.setAttribute('aria-label','Share '+edition.name+' '+edition.orientation+' on Farcaster');
 let opening=false;
 link.onclick=async event=>{
  if(!miniApp||event.button!==0||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey)return;
  event.preventDefault();if(opening)return;opening=true;link.setAttribute('aria-busy','true');
  try{await sdk.actions.composeCast(farcasterShareOptions(edition,location.origin));}
  catch{try{await sdk.actions.openUrl(link.href);}catch{$('status').textContent='Could not open Farcaster sharing. Please try again.';}}
  finally{opening=false;link.removeAttribute('aria-busy');}
 };
 return link;
}
function editionRecord(artworkExists,chain=null){
 const state=editionStatus({artworkExists,collectionReleased,chain});
 const record=document.createElement('dl');record.className='edition-record';record.setAttribute('aria-label','Artwork and NFT status');
 for(const [label,key] of [['Artwork','artwork'],['Mint','mint'],['Minted by','mintedBy'],['Owned by','ownedBy']]){
  const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=state[key];
  const address=state[key+'Address'];if(address){dd.title=address;dd.setAttribute('aria-label',address)}
  record.append(dt,dd);
 }
 return record;
}
function findEdition(id){return publishedEditions.find(edition=>edition.id===id)||previewEditions.find(edition=>edition.id===id);}
function openEdition(id,options={}){
 const edition=findEdition(id);if(!edition)return false;
 const row=registry.find(r=>r[0]===edition.name);if(!row)return false;
 openIsland(row,id,options);return true;
}

function acquisitionButtons(state,edition){
 const box=document.createElement('div');box.className='artwork-actions acquisition-actions';
 for(const action of islandActions(state)){
  const button=document.createElement('button');button.type='button';button.className=action==='buy'?'primary':'outline';
  if(action==='buy'){button.textContent='Buy · 750,000 $KEY';button.onclick=()=>openMint('direct',edition.id);}
  if(action==='luck'){button.textContent='Try your luck →';button.onclick=()=>openMint('blind');}
  if(action==='offer'){button.textContent='Make an offer';button.onclick=()=>openOffer(edition);}
  if(action==='reserve'){
   button.textContent='Reserve · 750,000 $KEY';button.disabled=true;
   const note=document.createElement('small');note.textContent='Reservations have not opened yet. Outbid step: 50,000 $KEY.';box.append(note);
  }
  box.append(button);
 }
 return box;
}
function openOffer(edition){
 let panel=$('selectedOffer');
 if(!panel){panel=document.createElement('article');panel.id='selectedOffer';panel.className='panel';$('trade').append(panel);}
 panel.replaceChildren();
 const title=document.createElement('h2');title.textContent='Make an offer';
 const selected=document.createElement('p');selected.textContent=edition.name+' · '+edition.orientation+' · #'+edition.id;
 const note=document.createElement('p');note.textContent='Offers are not open yet. No offer has been submitted and no payment will be requested.';
 const back=document.createElement('button');back.className='outline';back.textContent='← Back to island';back.onclick=()=>openEdition(edition.id,{fromIndex:true});
 panel.append(title,selected,note,back);show('trade');panel.scrollIntoView({block:'start'});
}
